\begin{definition}[Overlap graph]
\label{def:overlap}
Fix a composition $c$ with groups $j = 1,\dots,J$ and reference measures $\rho_j$ with supports
$U_j$, all dominated by a common $\sigma$-finite measure $\mu$. The \emph{overlap graph}
$\mathcal{G}_c$ has vertices $\{1,\dots,J\}$ and an edge $\{j,j'\}$ whenever some measurable set
$S$ satisfies $\rho_j(S) > 0$ and $\rho_{j'}(S) > 0$, so that the two constancy statements must
agree on $S$.
\end{definition}

\begin{theorem}[Local-to-global identifiability]
\label{thm:l2g}
Let the population objective $\sum_j \pi_j \Var_{\rho_j}[w]$ vanish, so $w \equiv b_j$
$\rho_j$-a.s.\ on $U_j$ for each $j$, and let $U_c = \bigcup_j U_j$. Then \emph{(i)}
$b_j = b_{j'}$ for every edge of $\mathcal{G}_c$, so the constants agree within each connected
component. Suppose in addition that each $\rho_j$ has a positive Lebesgue density on $U_j$ and that
$p_\theta(U_c \mid c) = 1$. Then \emph{(ii)} if $\mathcal{G}_c$ is connected, $w$ is a single
constant on $U_c$ and $p_\theta(\cdot \mid c) = \pi(\cdot \mid c)$; \emph{(iii)} if $\mathcal{G}_c$
has $C \ge 2$ components with regions $U^{(1)},\dots,U^{(C)}$, the zero-loss densities supported on
$U_c$ form the $(C-1)$-parameter family
\begin{equation}
  p_\theta(x \mid c) = e^{-b_i}e^{-E(c,x)/kT} \ \ (x \in U^{(i)}),
  \qquad \textstyle\sum_{i=1}^{C} e^{-b_i} Z^{(i)} = 1, \quad
  Z^{(i)} = \int_{U^{(i)}} e^{-E(c,x)/kT}\,\mathrm{d}x ,
  \label{eq:l2g}
\end{equation}
in which every vector of occupancies $\bigl(p_\theta(U^{(1)}),\dots,p_\theta(U^{(C)})\bigr)$ in the
open simplex is attained: the \emph{relative} mass of separated basins is not identified.
\end{theorem}

\subsection{What forces cannot identify}
\label{app:gauge}

This subsection is a purely mathematical statement about what gradient information
determines. It is \emph{not} an explanation of the gradient baseline's empirical
